// Bulk-imports each device.avif this catalog actually references, as a URL keyed by its folder
// path (e.g. "apple/iphone_15") — matches each entry's `framePath` below. Deliberately scoped to
// exactly those folders (brace-expanded, not a blanket **/device.avif) — assets/devices/ also has
// ipad/laptop/TV/gamepad frames for other, not-yet-built pickers; an unscoped glob would bundle
// all of those into the shipped extension for nothing.
const FRAME_IMAGES = import.meta.glob(
	'../../assets/devices/{apple/iphone_17-pro-max,apple/iphone_17-pro,apple/iphone_17,apple/iphone_17e,apple/iphone_air,apple/iphone_16-pro-max,apple/iphone_16-pro,apple/iphone_16-plus,apple/iphone_16,apple/iphone_15,apple/iphone_14_15-pro,apple/iphone_13_14,apple/iphone_13-mini,apple/iphone_x,apple/iphone_se-3,apple/iphone_6,apple/iphone_5,android/google/pixel-9-pro-xl,android/google/pixel-9-pro,android/google/pixel-9,android/google/pixel-8,android/samsung/galaxy-s26-ultra,android/samsung/galaxy-s26-plus,android/samsung/galaxy-s26,android/samsung/galaxy-s25-ultra,android/samsung/galaxy-s25-plus,android/samsung/galaxy-s25,android/samsung/galaxy-s22,android/samsung/galaxy-a56,android/samsung/galaxy-z-fold8-ultra,android/samsung/galaxy-z-fold8,android/samsung/galaxy-z-fold6,android/samsung/galaxy-z-flip8,android/samsung/galaxy-z-flip6,android/xiaomi/17-ultra,android/xiaomi/17-pro-max,android/xiaomi/17-pro,android/xiaomi/17,android/xiaomi/redmi-note-15-pro,android/xiaomi/poco-x8-pro,android/xiaomi/poco-x7-pro,android/xiaomi/poco-x7,android/oneplus/15,android/oneplus/13,android/oneplus/nord-ce5,android/motorola/edge-60-fusion,android/infinix/note-60-pro,android/infinix/hot-50-pro,android/huawei/mate-xt-ultimate,android/huawei/mate-x6}/device.avif',
	{ eager: true, query: '?url', import: 'default' }
) as Record<string, string>
function frameUrl(folder: string): string {
	const key = Object.keys(FRAME_IMAGES).find((k) => k.includes(`/devices/${folder}/`))
	if (!key) throw new Error(`No device frame image found for '${folder}'`)
	return FRAME_IMAGES[key]
}

