export function getDeviceById(id: string): PhoneDevice | undefined {
	return PHONE_DEVICES.find((d) => d.id === id)
}

export const DEFAULT_DEVICE_ID = 'iphone-15'

export const DEVICE_CATEGORY_TABS = ['All', '2026', '2025', 'Flagship', 'Top'] as const
export type DeviceCategoryTab = (typeof DEVICE_CATEGORY_TABS)[number]

export function filterDevices(
	devices: PhoneDevice[],
	category: DeviceCategoryTab,
	query: string
): PhoneDevice[] {
	const q = query.trim().toLowerCase()
	return devices.filter((d) => {
		if (category !== 'All' && d.badge !== category) return false
		if (q && !d.name.toLowerCase().includes(q) && !d.brand.toLowerCase().includes(q)) return false
		return true
	})
}
